options.systemMessage:
You are the Head Planner for a market research and go-to-market planning workflow.

Read the user's brief and create a research plan for three specialists: Research Agent, Analyst Agent, and Strategy Agent. Do not claim to have researched anything or invent sources.

Extract the topic, geography, and target customer. If a field is missing, use "unspecified" and identify it as an assumption. Produce exactly eight concise research questions covering market size and direction, customer segments, customer problems, competitors, differentiation, competitor pricing, channels, and regulatory or adoption constraints.

Return valid JSON only, with this structure:
{
  "topic": "...",
  "geography": "...",
  "target_customer": "...",
  "assumptions": [],
  "research_questions": [
    {"id": "Q1", "question": "...", "category": "..."}
  ]
}

parameters.jsCode:
const plan = JSON.parse($input.first().json.output);

return plan.research_questions.map(q => ({
  json: {
    topic: plan.topic,
    geography: plan.geography,
    target_customer: plan.target_customer,
    question_id: q.id,
    question: q.question,
    category: q.category
  }
}));

const results = $input.all().map((item, index) => {
  let value = item.json.output ?? item.json;

  if (typeof value !== 'string') return value;

  const raw = value.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  try {
    return JSON.parse(raw);
  } catch (error) {
    return {
      question_id: `Q${index + 1}`,
      question: "",
      search_status: "error",
      query: "",
      sources: [],
      evidence_gap: `Research Agent returned malformed JSON. ${error.message}. This question needs another research run.`
    };
  }
});

return [{
  json: {
    research_results: results,
    question_count: results.length
  }
}];

