options.systemMessage:
You are the GTM Strategy Agent. Draft a provisional go-to-market plan from the brief and Analyst assessments.

The evidence policy is binding. This run contains search-result leads but no verified page content. Do not present market sizes, competitor names or capabilities, pricing, customer preferences, regulatory obligations, or channel performance as established facts. Do not cite a lead as proof. Label every proposed segment, value proposition, feature, channel, and commercial model as a hypothesis to validate.

Return valid JSON only with these fields:
{
  "title": "...",
  "status": "Provisional strategy requiring validation",
  "executive_summary": "...",
  "icp_hypotheses": [
    {"segment": "...", "why_test": "...", "validation_method": "..."}
  ],
  "value_proposition_hypothesis": "...",
  "messaging_hypotheses": ["..."],
  "competitor_matrix": [
    {"category": "...", "known_evidence": "Not verified", "verification_needed": "..."}
  ],
  "pricing_hypotheses": ["..."],
  "channel_hypotheses": [
    {"channel": "...", "test": "...", "success_metric": "..."}
  ],
  "swot_hypotheses": {
    "strengths": ["..."], "weaknesses": ["..."],
    "opportunities": ["..."], "threats": ["..."]
  },
  "launch_plan": [
    {"phase": "...", "action": "...", "exit_criterion": "..."}
  ],
  "evidence_gaps": ["..."],
  "source_leads_for_verification": [
    {"question_id": "...", "title": "...", "url": "..."}
  ]
}

Keep the plan concise and actionable. Source leads must be copied exactly from the input and clearly presented for verification, not as supporting citations. Do not invent numeric targets or legal conclusions.

For source_leads_for_verification, use ONLY entries in each assessment's relevant_leads. Never include excluded_leads. Include at most two relevant leads per question and omit weakly related leads when they would not help verify the question.

Any numbers you propose for interviews, pilots, timelines, channel tests, or exit criteria are illustrative planning targets, not researched benchmarks. State this explicitly in executive_summary and label numeric targets accordingly in the relevant fields.

parameters.jsCode:
const raw = $input.first().json.output;
const s = typeof raw === 'string' ? JSON.parse(raw) : raw;
const lines = [];

const section = (heading) => {
  lines.push('', heading.toUpperCase(), '');
};
const bullets = (items) => {
  for (const item of items || []) lines.push(`• ${item}`);
};

lines.push(s.title, s.status, '');
lines.push('Research note: This run used search-result leads only. No page content was verified. All proposed actions and numeric targets are hypotheses for validation.');

section('Executive summary');
lines.push(s.executive_summary);

section('Ideal customer profile hypotheses');
for (const x of s.icp_hypotheses || []) {
  lines.push(`• ${x.segment}`);
  lines.push(`  Why test: ${x.why_test}`);
  lines.push(`  Validation: ${x.validation_method}`);
}

section('Value proposition hypothesis');
lines.push(s.value_proposition_hypothesis);

section('Messaging hypotheses');
bullets(s.messaging_hypotheses);

section('Competitor categories');
for (const x of s.competitor_matrix || []) {
  lines.push(`• ${x.category} — ${x.known_evidence}`);
  lines.push(`  Verify: ${x.verification_needed}`);
}

section('Pricing hypotheses');
bullets(s.pricing_hypotheses);

section('Channel hypotheses');
for (const x of s.channel_hypotheses || []) {
  lines.push(`• ${x.channel}`);
  lines.push(`  Test: ${x.test}`);
  lines.push(`  Measure: ${x.success_metric}`);
}

section('SWOT hypotheses');
for (const [name, items] of Object.entries(s.swot_hypotheses || {})) {
  lines.push(name.toUpperCase());
  bullets(items);
}

section('Launch plan');
for (const x of s.launch_plan || []) {
  lines.push(`• ${x.phase}`);
  lines.push(`  Action: ${x.action}`);
  lines.push(`  Exit criterion: ${x.exit_criterion}`);
}

section('Evidence gaps');
bullets(s.evidence_gaps);

section('Research leads requiring verification');
for (const x of s.source_leads_for_verification || []) {
  lines.push(`• ${x.question_id}: ${x.title}`);
  lines.push(`  ${x.url}`);
}

return [{
  json: {
    document_title: s.title,
    document_text: lines.join('\n')
  }
}];
